"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["88060"],{30975(e){e.exports=JSON.parse('{"id":"F484","slug":"insider-trading-disgorgement","name":"Insider Trading: Profit Gained and Maximum Civil Penalty","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Insider trading","level":"Beginner","aliases":["insider trading","loss avoided","disgorgement","three times profit"],"formula":{"latex":"G=q\\\\,(P_{after}-P_{trade}),\\\\quad \\\\text{Max civil penalty}=3G","also":[],"text":"Profit gained (buyer) = shares x (price after the news is public - price paid); Loss avoided (seller) = shares x (price paid originally - price after bad news); Disgorgement = profit gained or loss avoided; The US civil penalty can be up to three times that amount, in addition to disgorgement, and criminal penalties may apply"},"symbols":[{"symbol":"q","meaning":"Shares traded","unit":"shares"},{"symbol":"P_trade","meaning":"Price at which the insider traded","unit":"money"},{"symbol":"P_after","meaning":"Price after the information became public","unit":"money"}],"when_to_use":"Use it to see the scale of the money at stake in an insider trading case. Regulators ask the trader to give up the gain and may add a penalty of up to three times the gain. For a person who sold ahead of bad news, the same maths measures the loss avoided. Courts decide the actual amounts using their own rules.","worked_example":{"problem":"An employee buys 50,000 shares at 38.00 before a takeover bid is announced. The price rises to 52.00.","inputs":{"q":50000,"p0":38,"p1":52},"steps":[{"label":"Gain (disgorgement)","working":"50000 x (52-38)","value":"700,000.00"},{"label":"Maximum civil penalty (3 x gain)","working":"3 x 700000","value":"2,100,000.00"},{"label":"Total exposure with disgorgement","working":"700000+2,100,000","value":"2,800,000.00"},{"label":"Gain as a share of the amount invested","working":"700000 / (50000 x 38)","value":"36.8%"}],"answer":"The gain is 700,000.00. A civil penalty of up to three times the gain would be 2,100,000.00, so the total exposure with disgorgement is up to 2,800,000.00. The gain is 36.8% of the amount invested."},"calculator":{"available":true,"inputs":[{"id":"q","label":"Shares traded","unit":"","type":"number","default":50000,"hint":""},{"id":"p0","label":"Price paid","unit":"money","type":"number","default":38,"hint":""},{"id":"p1","label":"Price after the news","unit":"money","type":"number","default":52,"hint":""}],"checks":[{"expr":"q>0 and p0>0","message":"Shares and price must be above zero."}],"steps":[{"id":"g","label":"Gain (disgorgement)","expr":"q*(p1-p0)","format":"money"},{"id":"pen","label":"Maximum civil penalty (3 x gain)","expr":"3*g","format":"money"},{"id":"tot","label":"Total exposure with disgorgement","expr":"g+pen","format":"money"},{"id":"pct","label":"Gain as a share of the amount invested","expr":"g/(q*p0)","format":"pct1"}],"results":["g","pen","tot","pct"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"g":700000,"pen":2100000,"tot":2800000,"pct":0.3684210526315789}},"finder":{"finds":"The profit and maximum civil penalty in an insider case","needs":"Shares, price paid, price after the news"},"related":[{"slug":"short-swing-profit-16b","name":"Short-Swing Profit Recovery (US Section 16(b))"},{"slug":"abnormal-return-event-window","name":"Cumulative Abnormal Return before an Announcement"},{"slug":"market-manipulation-ratios","name":"Market Manipulation Screens: Order-to-Trade and Cancel Ratios"}],"related_ids":["F482","F483","F485"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>G</mi><mo>=</mo><mi>q</mi><mtext>\u2009</mtext><mo stretchy=\\"false\\">(</mo><msub><mi>P</mi><mrow><mi>a</mi><mi>f</mi><mi>t</mi><mi>e</mi><mi>r</mi></mrow></msub><mo>\u2212</mo><msub><mi>P</mi><mrow><mi>t</mi><mi>r</mi><mi>a</mi><mi>d</mi><mi>e</mi></mrow></msub><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Max\xa0civil\xa0penalty</mtext><mo>=</mo><mn>3</mn><mi>G</mi></mrow><annotation encoding=\\"application/x-tex\\">G=q\\\\,(P_{after}-P_{trade}),\\\\quad \\\\text{Max civil penalty}=3G</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"infrastructure-dscr-llcr","name":"Infrastructure Project: DSCR and Loan Life Cover"},"next":{"slug":"insurance-float-profit","name":"Insurance Underwriting Profit and Float"},"lesson":null,"total":522}')}}]);